update public.spell_catalog set
name_ru='Волшебная рука', casting_time='1 действие', spell_range='30 футов', area='1 спектральная рука', duration='1 минута', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Создаёте парящую спектральную руку. При появлении она может манипулировать предметом, открыть незапертую дверь или контейнер, убрать или достать вещь из открытого контейнера либо вылить содержимое флакона. В следующие ходы действием Магии можно снова управлять рукой и перемещать её до 30 футов.$$,
upcast='', notes='Рука исчезает, если оказывается дальше 30 футов от вас или если вы снова накладываете заклинание. Она не может атаковать, активировать магические предметы или переносить более 10 фунтов.',
author_description=$$Создаёшь дополнительную руку, потому что две собственные внезапно оказались недостаточно волшебными. Она открывает незапертое, таскает лёгкое и льёт содержимое флаконов, но драться за тебя отказывается.$$,
author_comment=$$Волшебник потратил годы обучения, чтобы не вставать за бутылкой со стола.$$, updated_at=now() where slug='mage-hand';

update public.spell_catalog set
name_ru='Починка', casting_time='1 действие', spell_range='Касание', area='1 разрыв или поломка размером не больше 1 фута', duration='Мгновенно', components=array['В','С','М'], material='два магнитных камня',
check_type='', damage='',
effect_summary=$$Чините один разрыв или поломку на объекте, которого касаетесь, если повреждение не больше 1 фута в любом измерении. Следов прежнего повреждения не остаётся.$$,
upcast='', notes='Можно физически починить магический предмет, но потерянные магические свойства заклинание не возвращает.',
author_description=$$Магически соединяет то, что кто-то сломал. Цепь, ключ, плащ, бурдюк — пока повреждение не слишком большое. Полезнейшая вещь в группе, где большинство проблем начинается словами «я просто хотел проверить».$$,
author_comment=$$Самое реалистичное заклинание для приключенцев: кто-то постоянно чинит последствия остальных.$$, updated_at=now() where slug='mending';

update public.spell_catalog set
name_ru='Сообщение', casting_time='1 действие', spell_range='120 футов', area='1 существо', duration='1 раунд', components=array['С','М'], material='кусочек медной проволоки',
check_type='', damage='',
effect_summary=$$Указываете на существо в пределах дистанции и шепчете сообщение. Только цель слышит его и может ответить шёпотом, который слышите только вы.$$,
upcast='', notes='Можно передавать через твёрдую преграду, если вы знакомы с целью и знаете, что она за ней. Заклинание блокируют магическая тишина, 1 фут камня, металла или дерева, а также тонкий лист свинца.',
author_description=$$Шепчешь человеку через всю комнату — или даже через стену, если достаточно хорошо знаешь, кто там сидит. Он может ответить так же тихо. Идеально для секретов, засад и людей, которые почему-то считают обычный разговор слишком социальным.$$,
author_comment=$$Телепатия для бедных. Зато медная проволока дешевле психотерапии.$$, updated_at=now() where slug='message';

update public.spell_catalog set
name_ru='Малая иллюзия', casting_time='1 действие', spell_range='30 футов', area='Звук или изображение предмета размером до куба 5 футов', duration='1 минута', components=array['С','М'], material='кусочек овечьей шерсти',
check_type='Действие Изучения: Интеллект (Расследование) против Сл заклинаний', damage='',
effect_summary=$$Создаёте звук или изображение предмета. Звук может быть от шёпота до крика и звучать непрерывно или отдельными фрагментами. Изображение предмета должно помещаться в куб 5 футов и не создаёт звука, света, запаха или других ощущений.$$,
upcast='', notes='Заклинание заканчивается, если наложить его снова. Физическое взаимодействие сразу выдаёт изображение как иллюзию. Успешная проверка Расследования также раскрывает обман, после чего иллюзия выглядит для этого существа бледной.',
author_description=$$Создаёшь небольшой звук или картинку предмета и надеешься, что никто не решит ткнуть в неё пальцем. Удивительно, сколько серьёзных планов приключенцев держится на предположении, что охранник ленивее, чем выглядит.$$,
author_comment=$$Иллюзия хороша ровно до первого идиота, который скажет: «А что если я её потрогаю?»$$, updated_at=now() where slug='minor-illusion';

update public.spell_catalog set
name_ru='Ядовитые брызги', casting_time='1 действие', spell_range='30 футов', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием', damage='1к12 урона ядом',
effect_summary=$$Выпускаете в цель облачко токсичного тумана. Совершаете дальнюю атаку заклинанием; при попадании цель получает 1к12 урона ядом.$$,
upcast='На 5 уровне урон становится 2к12, на 11 — 3к12, на 17 — 4к12.', notes='',
author_description=$$Бросаешь в противника порцию концентрированной токсичной дряни. Дистанция невелика, зато кубик урона солидный. Хороший выбор, если мысль «не дыши этим» пришла врагу уже после попадания.$$,
author_comment=$$Если друид предлагает тебе понюхать туман, сначала уточни, чей это туман.$$, updated_at=now() where slug='poison-spray';

update public.spell_catalog set
name_ru='Фокусы', casting_time='1 действие', spell_range='10 футов', area='Небольшой эффект в пределах дистанции', duration='Мгновенно или до 1 часа', components=array['В','С'], material=null,
check_type='', damage='',
effect_summary=$$Создаёте один малый магический эффект: безвредный сенсорный эффект; зажигаете или тушите свечу, факел или маленький костёр; очищаете или пачкаете объект объёмом до 1 куб. фута; нагреваете, охлаждаете или придаёте вкус неживому материалу объёмом до 1 куб. фута на 1 час; оставляете цвет, метку или символ на 1 час; либо создаёте безвредную безденежную безделушку или иллюзорное изображение в ладони до конца следующего хода.$$,
upcast='', notes='Одновременно может действовать до трёх немгновенных эффектов этого заклинания.',
author_description=$$Швейцарский нож мелкой магии: почистить одежду, испачкать чужую, подогреть еду, устроить запах, искры или маленький символ. Ни одно из этих умений не спасёт мир, зато именно поэтому ими пользуются чаще половины великих заклинаний.$$,
author_comment=$$Спасти королевство — раз в жизни. Убрать кровь с рукава перед ужином — каждую пятницу.$$, updated_at=now() where slug='prestidigitation';

update public.spell_catalog set
name_ru='Сотворение пламени', casting_time='1 бонусное действие', spell_range='На себя; бросок до 60 футов', area='1 пламя; при броске — 1 существо или объект', duration='10 минут', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием при броске', damage='1к8 огненного урона при попадании',
effect_summary=$$В руке появляется пламя, которое не греет и ничего не поджигает. Оно даёт яркий свет в радиусе 20 футов и тусклый ещё на 20. Пока заклинание действует, действием Магии можно метнуть пламя в цель в пределах 60 футов; при попадании она получает 1к8 огненного урона.$$,
upcast='На 5 уровне урон становится 2к8, на 11 — 3к8, на 17 — 4к8.', notes='Заклинание заканчивается, если наложить его снова. Само пламя в руке безопасно и не воспламеняет предметы.',
author_description=$$Друид держит в ладони безвредное пламя, освещает им дорогу, а потом при необходимости всё-таки бросает его в кого-нибудь и внезапно делает вредным. Удивительно последовательная философия природы.$$,
author_comment=$$Секунду назад это был милый костерёк. Теперь он летит тебе в лицо. Друиды вообще любят такие переходы.$$, updated_at=now() where slug='produce-flame';

update public.spell_catalog set
name_ru='Луч холода', casting_time='1 действие', spell_range='60 футов', area='1 существо', duration='Мгновенно', components=array['В','С'], material=null,
check_type='Дальняя атака заклинанием', damage='1к8 урона холодом',
effect_summary=$$Стреляете ледяным лучом. При попадании цель получает 1к8 урона холодом, а её Скорость уменьшается на 10 футов до начала вашего следующего хода.$$,
upcast='На 5 уровне урон становится 2к8, на 11 — 3к8, на 17 — 4к8.', notes='',
author_description=$$Обдаёшь цель холодом достаточно сильно, чтобы она не только получила урон, но и побежала медленнее. Иногда лучшая тактика — сделать так, чтобы проблема не успела добежать обратно.$$,
author_comment=$$Если враг всё ещё идёт к тебе после этого, возможно, пора перестать быть волшебником и начать убегать.$$, updated_at=now() where slug='ray-of-frost';

update public.spell_catalog set
name_ru='Сопротивление', casting_time='1 действие', spell_range='Касание', area='1 согласное существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null,
check_type='', damage='Уменьшает выбранный тип урона на 1к4, максимум один раз за ход',
effect_summary=$$Касаетесь согласного существа и выбираете тип урона: кислота, дробящий, холод, огонь, электричество, некротический, колющий, яд, излучение, рубящий или звук. Когда цель получает выбранный урон, она уменьшает общий полученный урон на 1к4.$$,
upcast='', notes='Существо может получить пользу от этого заклинания только один раз за ход. Требуется концентрация.',
author_description=$$Заранее выбираешь, что именно сегодня будет причинять товарищу меньше боли. Полезно, если вы хотя бы примерно знаете, чем вас собираются убивать. Такое в приключениях случается реже, чем хотелось бы.$$,
author_comment=$$Жрец назовёт это защитой свыше. Воин назовёт это «не стой в огне». Второй совет бесплатный.$$, updated_at=now() where slug='resistance';